SELECT p.slug project,l.root_path,d.path,d.document_kind,d.title,left(c.content,12000) excerpt,d.last_seen_at::text,d.freshness_status,'current project plan'::text reason,0::real score FROM source_documents d JOIN projects p ON p.id=d.project_id LEFT JOIN repository_locations l ON l.id=d.repository_location_id JOIN document_revisions v ON v.source_document_id=d.id AND v.is_current JOIN document_chunks c ON c.document_revision_id=v.id WHERE p.slug=$1 AND d.document_kind='plan' AND d.is_current AND d.freshness_status='current' ORDER BY d.last_seen_at DESC,d.path LIMIT 1
